class TransactionQueryLoggingContextTest {

	private final Map<String, String> originalMdc = MDC.getCopyOfContextMap();

	@AfterEach
	void restoreMdc() {
		if (originalMdc == null) {
			MDC.clear();
		} else {
			MDC.setContextMap(originalMdc);
		}
	}

	@ParameterizedTest
	@EnumSource(QueryForm.class)
	void queryLoggingContextCrossesTransactionThreadWithoutLeakingToTheNextRequest(QueryForm form) throws Exception {
		Repository repository = mock(Repository.class);
		RepositoryConnection connection = mock(RepositoryConnection.class);
		when(repository.getConnection()).thenReturn(connection);
		when(connection.getParserConfig()).thenReturn(new ParserConfig());
		AtomicReference<Map<String, String>> workerContext = new AtomicReference<>();
		when(connection.getNamespace("probe")).thenAnswer(invocation -> {
			workerContext.set(readLoggingContext());
			return null;
		});
		try (Transaction transaction = new Transaction(repository)) {
			MDC.put("org.eclipse.rdf4j.requestId", "process:one:request:17");
			MDC.put("org.eclipse.rdf4j.repositoryId", "test-repo");
			MDC.put("traceId", "trace-one");
			MDC.put("spanId", "span-one");
			MDC.put("unrelated", "must-not-propagate");
			Map<String, String> before = MDC.getCopyOfContextMap();
			AtomicReference<Map<String, String>> observed = new AtomicReference<>();
			AtomicReference<Thread> evaluationThread = new AtomicReference<>();
			evaluate(transaction, form, () -> {
				observed.set(readLoggingContext());
				evaluationThread.set(Thread.currentThread());
			}, true);

			assertThat(observed.get()).containsEntry("org.eclipse.rdf4j.requestId", "process:one:request:17")
					.containsEntry("org.eclipse.rdf4j.repositoryId", "test-repo")
					.containsEntry("org.eclipse.rdf4j.transactionId", transaction.getID().toString())
					.containsEntry("traceId", "trace-one")
					.containsEntry("spanId", "span-one")
					.containsEntry("unrelated", null);
			assertThat(evaluationThread.get()).isNotSameAs(Thread.currentThread());
			assertThat(MDC.getCopyOfContextMap()).isEqualTo(before);

			transaction.getNamespace("probe");
			assertThat(workerContext.get().values()).containsOnlyNulls();

			MDC.remove("org.eclipse.rdf4j.requestId");
			MDC.remove("org.eclipse.rdf4j.repositoryId");
			MDC.remove("traceId");
			MDC.remove("spanId");
			evaluate(transaction, form, () -> observed.set(readLoggingContext()), false);
			assertThat(observed.get()).containsEntry("org.eclipse.rdf4j.requestId", null)
					.containsEntry("org.eclipse.rdf4j.repositoryId", null)
					.containsEntry("org.eclipse.rdf4j.transactionId", transaction.getID().toString())
					.containsEntry("traceId", null)
					.containsEntry("spanId", null);
		}
	}

	private void evaluate(Transaction transaction, QueryForm form, Runnable capture, boolean breakerOverload)
			throws Exception {
		switch (form) {
		case BOOLEAN:
			BooleanQuery bool = mock(BooleanQuery.class);
			when(bool.evaluate()).thenAnswer(invocation -> {
				capture.run();
				return true;
			});
			if (breakerOverload) {
				transaction.evaluate(null, bool);
			} else {
				transaction.evaluate(bool);
			}
			break;
		case TUPLE:
			TupleQuery tuple = mock(TupleQuery.class);
			when(tuple.evaluate()).thenAnswer(invocation -> {
				capture.run();
				return mock(TupleQueryResult.class);
			});
			try (TupleQueryResult result = breakerOverload ? transaction.evaluate(null, tuple)
					: transaction.evaluate(tuple)) {
				result.hasNext();
			}
			break;
		case GRAPH:
			GraphQuery graph = mock(GraphQuery.class);
			when(graph.evaluate()).thenAnswer(invocation -> {
				capture.run();
				return mock(GraphQueryResult.class);
			});
			try (GraphQueryResult result = breakerOverload ? transaction.evaluate(null, graph)
					: transaction.evaluate(graph)) {
				result.hasNext();
			}
			break;
		case EXPLAIN:
			Query query = mock(Query.class);
			when(query.explain(Explanation.Level.Executed)).thenAnswer(invocation -> {
				capture.run();
				return mock(Explanation.class);
			});
			if (breakerOverload) {
				transaction.explain(null, query, Explanation.Level.Executed);
			} else {
				transaction.explain(query, Explanation.Level.Executed);
			}
			break;
		}
	}

	private Map<String, String> readLoggingContext() {
		Map<String, String> context = new HashMap<>();
		for (String key : new String[] { "org.eclipse.rdf4j.requestId", "org.eclipse.rdf4j.repositoryId",
				"org.eclipse.rdf4j.transactionId", "traceId", "spanId", "unrelated" }) {
			context.put(key, MDC.get(key));
		}
		return context;
	}

	private enum QueryForm {
		BOOLEAN,
		TUPLE,
		GRAPH,
		EXPLAIN
	}
}
